mapper.select:
SELECT s.standings_id, s.team_id, s.position, s.played_games, s.won, s.draw, s.lost, s.points, s.goals_for,
       s.goals_against, s.goal_difference, s.season, s.league,
       t.team_id, t.name AS team_name, t.logo
FROM standings s INNER JOIN team t ON s.team_id = t.team_id
WHERE s.league = #{league} AND s.season = #{season}
ORDER BY s.points DESC, s.goal_difference DESC, s.goals_for DESC;

SELECT s.standings_id, s.team_id, s.position, s.played_games, s.won, s.draw, s.lost, s.points, s.goals_for,
       s.goals_against, s.goal_difference, s.season, s.league,
       t.team_id, t.name AS team_name, t.logo
FROM standings s INNER JOIN team t ON s.team_id = t.team_id
WHERE s.season = #{season}
ORDER BY s.points DESC, s.goal_difference DESC, s.goals_for DESC;

mapper.insert:
insert into standings ( standings_id, team_id, position, played_games, won, draw, lost, points, goals_for, goals_against,goal_difference, season, league ) values
( #{standingsDto.standingsId}, #{standingsDto.teamDto.teamId}, #{standingsDto.position}, #{standingsDto.playedGames}, #{standingsDto.won}, #{standingsDto.draw}, #{standingsDto.lost}, #{standingsDto.points}, #{standingsDto.goalsFor}, #{standingsDto.goalsAgainst}, #{standingsDto.goalDifference}, #{standingsDto.season}, #{standingsDto.league} )
on DUPLICATE key update standings_id = VALUES(standings_id), team_id = VALUES(team_id), position = VALUES(position), played_games = VALUES(played_games), won = VALUES(won), draw = VALUES(draw), lost = VALUES(lost), points = VALUES(points), goals_for = VALUES(goals_for), goals_against = VALUES(goals_against), goal_difference = VALUES(goal_difference), season = VALUES(season), league = VALUES(league);
